DROP TABLE IF EXISTS `base_dungeon`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon` (
  `id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本id',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '副本名字@lang@',
  `type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本类型##0:普通副本、1:诛仙塔、2:铜钱副本、3:宠物副本、4:经验副本、5：装备副本、6：五行副本、7、塔防副本（预留）',
  `npc_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '入口NPC##NPCID',
  `cost` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '进入消耗(门票)##[{Type, GoodsType, Num}] 或者 [{X,Y,[{Type, GoodsType, Num}]}]：取X <= 目标次数 <= Y 的消耗',
  `is_auto_buy_sweep` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否自动购买扫荡',
  `sweep_lv` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '可扫荡等级##0：不可以扫荡，>0的等级就可以扫荡',
  `sweep_cost` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '扫荡消耗##[{Type, GoodsType, Num},...]',
  `level_change_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '关卡切换类型',
  `diff_lv` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '副本难度##0:无,1:普通,2:困难,3:地狱',
  `scene_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '场景id',
  `scene_list` varchar(200) NOT NULL DEFAULT '[]' COMMENT '场景列表## 关联的所有场景',
  `scene_out` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '退出副本##[场景ID，X，Y]',
  `count_deduct` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '次数扣除',
  `revive_type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '复活类型(0:不允许复活;1:复活时间叠加;2:复活时间不叠加)',
  `revive_count` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '复活次数',
  `revive_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '复活秒数',
  `wave_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本波数',
  `time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本时间',
  `count_cond` text NOT NULL COMMENT '次数条件##[{类型(1:日次数;2:周次数;3:终身次数;4:每日助战次数), 次数上限}]',
  `condition` text NOT NULL COMMENT '条件##等级，组队，职业，互为异性，任务',
  `open_begin` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '开服时段开始天数',
  `open_end` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '开服时段结束天数',
  `start_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '活动开始时间',
  `end_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '活动结束时间',
  `week_list` varchar(50) NOT NULL DEFAULT '[]' COMMENT '星期开放列表',
  `mon_event` text NOT NULL COMMENT '刷怪事件',
  `story_event` text NOT NULL COMMENT '剧情事件',
  `zone_event` text NOT NULL COMMENT '区域事件',
  `scene_event` text NOT NULL COMMENT '场景事件',
  `success_event` text NOT NULL COMMENT '通关事件',
  `fail_event` text NOT NULL COMMENT '失败事件',
  `push_settlement_type` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '推结算类型##需要配合 {quit_time,Time} 使用,来处理退出的结算',
  `dynamic_attr` text NOT NULL COMMENT '动态属性',
  `recommend_power` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '推荐战力',
  `power_crush_type` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '战力碾压类型',
  `buy_count_cost` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '次数购买消耗',
  `extra_reward` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '额外奖励##1:通关后手动领取,只能领取一次的奖励;2:通关处理; [{奖励类型(1:普通 2:顶级 3:首次), [{Type, GoodsTypeId, Num},..]}],首次奖励=> [{3, {奖励类型, [ {主键, [{Type, GoodsTypeId, Num}]}, ...] }},...]',
  `battle_countdown_time` int(11) unsigned NOT NULL COMMENT '战斗倒计时(秒)',
  `exit_countdown_type` varchar(50) NOT NULL COMMENT '战斗结束后退出倒计时类型 [{Type(1:结束后倒计时退出, 2:暂无), Value}]',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本配置';
/*!40101 SET character_set_client = @saved_cs_client */;
