DROP TABLE IF EXISTS `base_dungeon_clear`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon_clear` (
  `dun_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '副本id',
  `scene_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '场景id',
  `wave_list` text NOT NULL COMMENT '对应的波数##[{波数类型, 波数子类型}]',
  `clear_mon_list` text NOT NULL COMMENT '清理的怪物列表##[MonId,...]',
  PRIMARY KEY (`dun_id`,`scene_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本清理配置';
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `base_dungeon_clear` VALUES (2100,2100,'[{11,1},{12,1},{13,1},{14,1}]','[2100016,2100017,2100018,2100019,2100020,2100021,2100022,2100023,2100024,2100025]');
DROP TABLE IF EXISTS `base_dungeon_grade`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon_grade` (
  `dun_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本id',
  `grade` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '等级',
  `min_score` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '最小分数',
  `max_score` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '最大分数',
  `reward` text,
  `draw_list` varchar(256) NOT NULL DEFAULT '[]' COMMENT '抽奖列表',
  PRIMARY KEY (`dun_id`,`min_score`,`max_score`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本评分配置';
/*!40101 SET character_set_client = @saved_cs_client */;
