DROP TABLE IF EXISTS `base_dungeon_level`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon_level` (
  `dun_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本id',
  `scene_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本场景id',
  `serial_no` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '序号##顺序关卡需要使用的，顺序关卡副本不能有相同的serial_no',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '名字@lang@',
  `desc` varchar(1000) NOT NULL DEFAULT '' COMMENT '描述@lang@',
  `time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '时间',
  `wave_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本波数',
  `mon_event` text NOT NULL COMMENT '刷怪事件##[ {事件编号ID1, 波数类型1, 参数列表, [{触发元素1},{触发元素2},...}]}, {事件编号ID2, 波数类型2, 参数列表, [{触发元素3},{触发元素4},...}]},...]',
  `story_event` text NOT NULL COMMENT '剧情事件##[ {事件编号ID1, [剧情配置ID1, 剧情子类型], [{触发元素1},{触发元素2},...}]}, {事件编号ID2, [剧情ID配置2, 剧情子类型], [{触发元素3},{触发元素4},...}]},...]',
  `zone_event` text NOT NULL COMMENT '区域事件##[ {事件编号ID1, 区域配置ID1, 切换状态, [{触发元素1},{触发元素2},...}]}, {事件编号ID2, 区域ID配置2, 切换状态, [{触发元素3},{触发元素4},...}]},...]',
  `scene_event` text NOT NULL COMMENT '场景事件##[ {事件编号ID1, 参数列表, [{触发元素1},{触发元素2},...}]}, {事件编号ID2, 场景id, 参数列表, [{触发元素3},{触发元素4},...}]} }] },...]',
  `success_event` text NOT NULL COMMENT '通关事件##[ {类型(0:直接结算,1:只推送结算信息), [{触发元素1},{触发元素2},...}]}, {类型, [{触发元素3},{触发元素4},...}]},...]',
  `fail_event` text NOT NULL COMMENT '失败事件##[ {类型(0:直接结算,1:只推送结算信息), [{触发元素1},{触发元素2},...}]}, {类型, [{触发元素3},{触发元素4},...}]},...]',
  PRIMARY KEY (`dun_id`,`scene_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本关卡配置';
/*!40101 SET character_set_client = @saved_cs_client */;
