CREATE TABLE `base_dungeon_score` (
  `dun_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本id',
  `same_guild_score` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '同公会加分',
  `friend_score` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '好友加分',
  `intimacy_score_list` text NOT NULL COMMENT '亲密度等级加分##[{最小亲密度等级,最大亲密度等级,加分}]',
  `time_score_list` text NOT NULL COMMENT '时间加分##[{耗时开始时间,耗时结束时间,加分}]',
  `mon_score_list` text NOT NULL COMMENT '怪物加分##[{怪物id,加分}]',
  PRIMARY KEY (`dun_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本加分配置';
