DROP TABLE IF EXISTS `base_dungeon_setting`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon_setting` (
  `dun_key` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本key##副本id或副本类型,要跟程序协商好',
  `type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '设置类型',
  `select_type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '选择类型##用于一些选项,比如消耗之类的',
  `cost` varchar(200) NOT NULL DEFAULT '[]' COMMENT '消耗',
  PRIMARY KEY (`dun_key`,`type`,`select_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本设置配置';
/*!40101 SET character_set_client = @saved_cs_client */;
