DROP TABLE IF EXISTS `base_dungeon_sweep_rewards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon_sweep_rewards` (
  `dun_id` int(10) unsigned NOT NULL COMMENT '副本id',
  `score_min` int(10) unsigned NOT NULL COMMENT '记录范围下限',
  `score_max` int(10) unsigned NOT NULL COMMENT '记录范围上限',
  `rewards` varchar(2048) DEFAULT NULL,
  `drop_list` varchar(256) NOT NULL DEFAULT '[]' COMMENT '抽奖列表',
  PRIMARY KEY (`dun_id`,`score_min`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='扫荡奖励配置';
