/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_dungeon_wave` (
  `dun_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '副本id',
  `scene_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '场景id',
  `type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '波数类型',
  `subtype` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '波数子类型',
  `rand_num` text NOT NULL COMMENT '随机数量',
  `mon_list` text NOT NULL COMMENT '怪物信息',
  `group_mon_list` text NOT NULL COMMENT '组怪物信息##[{GroupWeight(组权重), [{MonId, X, Y, MonWeight, AttrList},...]},...] MonWeight:权重,怪物MonId:怪物id,[X,Y]:坐标,AttrList:属性列表(默认填[])',
  `xy_range` varchar(100) NOT NULL DEFAULT '[]' COMMENT '坐标波动',
  `refresh_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '刷怪时间',
  `create_type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '生成怪物类型##0:循环刷新,1:怪物死亡刷新,2:最大刷新是循环时间(死亡间隔和循环时间一起使用,最大的刷新时间是循环间隔)',
  `cycle_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '循环次数',
  `cycle_gap` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '循环间隔',
  `die_gap` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '死亡间隔',
  `msg_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '消息推送时间',
  `msg_stay_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '消息停留时间',
  `msg` varchar(200) NOT NULL DEFAULT '' COMMENT '消息@lang@',
  `desc` varchar(1000) NOT NULL DEFAULT '' COMMENT '描述@lang@',
  PRIMARY KEY (`dun_id`,`scene_id`,`type`,`subtype`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='副本波数配置';
/*!40101 SET character_set_client = @saved_cs_client */;
