DROP TABLE IF EXISTS `base_goods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_goods` (
  `goods_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '物品编号',
  `goods_name` varchar(50) NOT NULL DEFAULT '[]' COMMENT '物品名称@lang@',
  `intro` text NOT NULL COMMENT '物品描述信息@lang@',
  `getway` text NOT NULL COMMENT '获得途径@lang@',
  `getway_url` varchar(255) NOT NULL DEFAULT '[]' COMMENT '获取途径链接',
  `bind` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '绑定类型，0非绑，1绑定 ',
  `trade` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否交易，0不可交易，1可交易',
  `if_custom_price` varchar(64) NOT NULL COMMENT '是否可自定义交易价格(0否,1是)',
  `sell` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否出售，0不可出售 ，1可出售',
  `type` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '物品类型ID',
  `subtype` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '物品子类型ID',
  `sell_category` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '市场商品类型',
  `sell_subcategory` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '市场商品子类型',
  `equip_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '装备类型，0为无',
  `goods_icon` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '物品图标',
  `career_id` smallint(5) unsigned NOT NULL DEFAULT '0' COMMENT '职业限制，0为不限',
  `level` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '等级需求，0为不限',
  `max_overlap` mediumint(8) unsigned NOT NULL DEFAULT '99999' COMMENT '可叠加数，0为不可叠加',
  `color` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '物品颜色，0 白色，1 绿色，2 蓝色，3 紫色，4 黄色，5 橙色，6 红色',
  `expire_time` varchar(50) NOT NULL DEFAULT '0' COMMENT '有效期，0为不限，单位为秒',
  `trade_price` varchar(512) NOT NULL DEFAULT '[]' COMMENT '交易基准价格',
  `lock_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '交易锁定期',
  `use` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '是否可使用，(0：不可使用，1：可使用)',
  `compose` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '是否可合成，(0：不可合成，1：可合成)',
  `quick_use` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '获得立即使用',
  `use_one_key` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '一键使用',
  `base_attrlist` varchar(512) NOT NULL DEFAULT '[]' COMMENT ' [{属性类型,值}]',
  `addition` varchar(512) NOT NULL DEFAULT '[]' COMMENT '附加属性',
  `skill` varchar(64) NOT NULL DEFAULT '[]' COMMENT '技能',
  `model_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '模型资源id',
  `sex` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '性别限制##0为不限，1男，2女',
  `turn` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '转职限制##0为不限，1为1转，2为2转，以此类推...需要向下兼容，1转开启的道具，2转3转N转也可以使用',
  `jump` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否可以跳转:0否;1是，仅用于显示“跳转”按钮，和“使用”字段互斥，只能有一个填“1”',
  `bag_location` tinyint(1) unsigned NOT NULL DEFAULT '4' COMMENT '背包位置',
  `effect_id` int(11) NOT NULL DEFAULT '0' COMMENT '特效资源id',
  `source` text NOT NULL COMMENT '物品来源',
  `expire_type` tinyint(4) NOT NULL COMMENT '有效期类型',
  `can_storge` tinyint(2) NOT NULL DEFAULT '1' COMMENT '能否存储于仓库',
  PRIMARY KEY (`goods_id`),
  KEY `type` (`type`),
  KEY `subtype` (`subtype`)
