DROP TABLE IF EXISTS `base_goods_compose`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_goods_compose` (
  `id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '合成id',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '名字@lang@',
  `extra` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '合成类型',
  `role_lv` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '所需玩家等级',
  `sex` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '性别',
  `condition` varchar(255) NOT NULL DEFAULT '[]' COMMENT '开启条件',
  `subtype` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '合成方式',
  `regular_mat` varchar(2048) NOT NULL DEFAULT '[]' COMMENT '固定材料',
  `irregular_mat` varchar(1024) NOT NULL DEFAULT '[]' COMMENT '不固定材料',
  `hole_list` varchar(64) NOT NULL DEFAULT '[]' COMMENT '孔位列表',
  `cost` varchar(255) NOT NULL DEFAULT '[]' COMMENT '合成消耗',
  `goods` varchar(255) NOT NULL DEFAULT '[]' COMMENT '合成物品',
  `fail_goods` varchar(64) NOT NULL DEFAULT '[]' COMMENT '失败奖励',
  `ratio_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '概率类型',
  `ratio` varchar(255) NOT NULL DEFAULT '' COMMENT '概率',
  `bind_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '绑定类型',
  `tv_type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '传闻id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='合成规则';
/*!40101 SET character_set_client = @saved_cs_client */;
