CREATE TABLE `base_goods_effect` (
  `goods_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '物品类型id',
  `goods_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '道具类型',
  `buff_type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'BUFF类型ID',
  `effect_list` varchar(1024) NOT NULL COMMENT '效果',
  `time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '持续时长(秒)',
  `limit_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '限制类型',
  `counter_module` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '次数模块ID',
  `counter_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '次数ID',
  `limit_scene` varchar(255) NOT NULL COMMENT '生效的场景ID',
  `desc` varchar(1024) NOT NULL COMMENT '描述',
  PRIMARY KEY (`goods_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='物品效果配置';
