DROP TABLE IF EXISTS `base_goods_exchange`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_goods_exchange` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '标题@lang@',
  `npc` int(11) unsigned NOT NULL DEFAULT '0' COMMENT 'NPC编号',
  `type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '兑换类型，0 物品兑换，1 竞技积分兑换',
  `method` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '兑换方式，0为固定兑换，1为随机兑换',
  `raw_goods` text NOT NULL COMMENT '原物品列表',
  `dst_goods` text NOT NULL COMMENT '兑换物品列表',
  `bind` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '兑换物品的绑定状态',
  `max_overlap` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '兑换物品的最大叠加数',
  `exchange_type` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '兑换类型，0:单日物品兑换; 1:每周物品的兑换; 2:日和周都要计算的类型（暂时只做0的类型',
  `limit_week_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '限制兑换数的每次次数类型Id(物品兑换每周限制专用区间17001 - 18500)',
  `limit_week_num` int(11) NOT NULL COMMENT '每周兑换的次数',
  `limit_day_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '限制兑换数的日常次数类型Id(物品兑换每日限制专用区间18501 - 20000)',
  `limit_day_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '每天能兑换的次数',
  `start_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '开始时间，0为不限',
  `end_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '结束时间，0为不限',
  `condition` varchar(1000) DEFAULT '[]' COMMENT '开启条件',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '状态，1为生效，0为不生效',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='物品兑换规则表';
/*!40101 SET character_set_client = @saved_cs_client */;
DROP TABLE IF EXISTS `base_goods_exchange_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_goods_exchange_rule` (
  `id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '兑换规则id',
  `type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '兑换类型',
  `role_lv` smallint(2) unsigned NOT NULL DEFAULT '0' COMMENT '需要玩家等级',
  `cost_list` varchar(255) NOT NULL DEFAULT '[]' COMMENT '消耗物品',
  `obtain_list` varchar(255) NOT NULL DEFAULT '[]' COMMENT '获得物品',
  `lim_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '次数限制类型 0: 不限制 1: 每天限制 2: 每周限制 3: 终身限制',
  `module` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '功能id',
  `sub_module` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '模块子功能id 模块id+模块子功能id额外计数器配置找到对应配置',
  `lim_num` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '限制兑换数量',
  `condition` varchar(255) NOT NULL DEFAULT '[]' COMMENT '兑换条件',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='物品兑换规则';
/*!40101 SET character_set_client = @saved_cs_client */;
