DROP TABLE IF EXISTS `base_mon`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_mon` (
  `id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '怪物配置id',
  `name` varchar(50) NOT NULL COMMENT '怪物名字@lang@',
  `kind` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '怪物类型 0怪物，1采集怪，2任务采集怪，3护送车队，4拾取型，5赏金怪',
  `boss` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT 'BOSS类型，0普通怪，1野外BOSS，2英灵殿BOSS',
  `mon_sys` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '怪物系统类型##用于判断怪物对应的玩法，处理成就任务等，填0就走通用.',
  `type` tinyint(3) unsigned DEFAULT '1' COMMENT '战斗类型(0被动，1主动)',
  `career` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '职业,0没职业',
  `color` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '颜色(1白,2绿,3蓝,4紫,5粉,6橙,7金)',
  `auto` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0-读怪物表属性，1-服务器等级，2-队伍平均等级，3-队长等级（无组队时默认是队长），需要读怪物动态属性表',
  `icon` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '资源id',
  `icon_scale` varchar(10) DEFAULT '1.0' COMMENT '资源缩放[1.0-]',
  `icon_effect` varchar(100) NOT NULL DEFAULT '' COMMENT '怪物资源特效',
  `icon_texture` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '贴图id',
  `weapon_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '武器模型id',
  `foot_icon` varchar(200) NOT NULL DEFAULT '""' COMMENT '脚下资源id',
  `direction` smallint(5) NOT NULL DEFAULT '-1' COMMENT '默认朝向(0-360), -1为随机方向',
  `desc` varchar(5000) DEFAULT NULL COMMENT '默认对话##时间,怪物说话:概率,怪物说话:概率,怪物说话:概率 ',
  `lv` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '等级',
  `hp_lim` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '血上限',
  `hp_num` int(11) unsigned DEFAULT '0' COMMENT '血条数量',
  `att` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '攻击',
  `def` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '防御',
  `hit` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '命中',
  `dodge` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '躲闪',
  `crit` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '暴击',
  `ten` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '坚韧',
  `wreck` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '破甲',
  `resist` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '抗性',
  `special_attr` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '特定属性[{AttrType, AttrValue}] = [{属性类型,属性值}]',
  `resum` varchar(200) NOT NULL DEFAULT '[]' COMMENT '回血配置,[回血模式,回复量,时间]回血模式:0不回血;1脱离战斗状态立刻回满血;2战斗中持续回复;3脱离战斗后持续回复',
  `striking_distance` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '攻击距离(像素)',
  `tracing_distance` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '跟踪距离(像素)',
  `warning_range` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '警戒范围(像素)',
  `hate_range` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '仇恨范围(像素)：表示玩家离开某区域后，怪物不追踪，清空伤害列表，不填表示没有仇恨范围',
  `speed` int(3) unsigned NOT NULL DEFAULT '0' COMMENT '速度(每秒移动的像素)',
  `skill` varchar(2000) NOT NULL DEFAULT '[]' COMMENT '技能列表[{技能id,技能等级},...]',
  `retime` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '重生时间(毫秒)',
  `att_time` int(11) unsigned NOT NULL DEFAULT '400' COMMENT '攻击间隔(毫秒)',
  `att_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '0近攻，1远程攻击',
  `drop` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '掉落方式',
  `exp` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '经验',
  `out` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '挂机设置 0|1,是否玩家自动挂机可以攻击的目标',
  `collect_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '采集时间(秒)',
  `collect_count` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '可采集次数（每次都会有掉落）',
  `is_fight_back` tinyint(1) unsigned DEFAULT '1' COMMENT '是否会反击 ，默认为1',
  `is_be_atted` tinyint(1) unsigned DEFAULT '1' COMMENT '是否可攻击 ，默认为1',
  `is_be_clicked` tinyint(1) unsigned DEFAULT '1' COMMENT '是否可被点击，默认为1',
  `is_armor` tinyint(1) unsigned DEFAULT '0' COMMENT '是否霸体，默认为0',
  `del_hp_each_time` varchar(300) NOT NULL DEFAULT '[]' COMMENT '[Min,Max]:怪物受到的每次伤害值区间,整数,小数为百分比：1:默认:[];2:hurt大于等于Min小于等于Max;3怪物Hp的百分比:Hurt大于等于Hp*Min小于等于Hp*Max',
  `figure_visible` tinyint(4) unsigned DEFAULT '1' COMMENT '是否显示形象（默认1，1：显示；0：不显示）',
  `mon_state` varchar(255) NOT NULL COMMENT '怪物出生特殊状态(特效展示),0：代表无特效，客户端使用',
  `mon_die_state` varchar(255) NOT NULL DEFAULT '' COMMENT '怪物死亡特殊状态##(特效展示),0：代表无特效，客户端使用',
  `is_hide_hp` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '是否隐藏血条(0|1)',
  `is_hit_ac` tinyint(2) unsigned NOT NULL DEFAULT '1' COMMENT '是否播放受击动作',
  `is_hit_color` tinyint(2) unsigned NOT NULL DEFAULT '1' COMMENT '是否播放受击颜色（0|1）',
  `exp_share_type` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '经验分享类型##0所有伤害者都获得全部经验 1按伤害比例分配 2场景内共享 ',
  `anger` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '杀怪玩家增加的怒气值',
  `load_immediately` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否立即加载 0:不立即加载 1:立即加载',
  `drop_lv_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '掉落等级类型',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='怪物信息';
/*!40101 SET character_set_client = @saved_cs_client */;
