CREATE TABLE `base_mon_checkin_mutiple` (
  `lv_node` int(20) NOT NULL COMMENT '等级节点',
  `month_id` int(11) NOT NULL COMMENT '月份',
  `multiple` decimal(20,2) NOT NULL COMMENT '普通用户倍数',
  `vip_lv` int(11) NOT NULL COMMENT '使用vip倍数需要达到的vip等级',
  `vip_multiple` decimal(20,2) NOT NULL COMMENT 'vip奖励倍数',
  PRIMARY KEY (`lv_node`,`month_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='不同等级区间配置不同的奖励倍数和vip倍数';
