DROP TABLE IF EXISTS `base_mon_drop_gift_type`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_mon_drop_gift_type` (
  `type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '类型',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT '描述@lang@',
  PRIMARY KEY (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='掉落礼包类型配置';
