DROP TABLE IF EXISTS `base_mon_drop_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_mon_drop_rule` (
  `act_id` smallint(5) unsigned NOT NULL DEFAULT '1' COMMENT '活动主id',
  `sub_id` smallint(5) unsigned NOT NULL DEFAULT '1' COMMENT '主动子id',
  `mon_sys` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '怪物系统类型',
  `slv` int(11) unsigned NOT NULL DEFAULT '1' COMMENT '开始等级',
  `elv` int(11) unsigned NOT NULL DEFAULT '99' COMMENT '结束等级',
  `drop_list` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '掉落列表',
  `drop_rule` varchar(1000) DEFAULT '[]' COMMENT '掉落规则',
  PRIMARY KEY (`act_id`,`sub_id`,`mon_sys`,`slv`,`elv`)
