DROP TABLE IF EXISTS `base_recharge_product_vip`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_recharge_product_vip` (
  `product_id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `vip_exp` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '增加VIP经验',
  `desc` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='礼包vip经验配置';
/*!40101 SET character_set_client = @saved_cs_client */;
DROP TABLE IF EXISTS `base_scene`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_scene` (
  `id` int(11) NOT NULL COMMENT '场景id',
  `name` char(20) NOT NULL COMMENT '场景名@lang@',
  `type` int(1) NOT NULL DEFAULT '0' COMMENT '场景大类 0 主城1 野外 2 副本',
  `subtype` int(1) NOT NULL COMMENT '场景子类 0 普通,1 安全场景',
  `cls_type` int(1) NOT NULL COMMENT '是否跨服场景 0 非跨服 | 1 跨服',
  `broadcast` int(1) DEFAULT NULL COMMENT '广播类型 0九宫格 | 1全场景',
  `origin_type` int(1) unsigned NOT NULL DEFAULT '0' COMMENT '原点类型',
  `mount` int(1) NOT NULL COMMENT '是否可上坐骑',
  `x` int(11) NOT NULL COMMENT '默认x坐标',
  `y` int(11) NOT NULL COMMENT '默认y坐标',
  `is_have_safe_area` int(1) NOT NULL COMMENT '是否有安全区 0 否 | 1是',
  `width` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '场景横向长度(最大12000像素)',
  `height` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '场景纵向长度',
  `elem` text NOT NULL COMMENT '传送阵列表(格式:[{NextSceneId, x, y},...])',
  `npc` text NOT NULL COMMENT '场景NPC,数据结构(格式:[{NpcId, x, y},...])',
  `mon` text NOT NULL COMMENT '场景怪物,数据结构([{怪物id, x, y, 是否主动(0|1),分组id},...])',
  `mask` longtext NOT NULL COMMENT '障碍点',
  `jump` text NOT NULL COMMENT '跳跃点(格式:[{编号, 目的X, 目的Y},...])',
  `dynamicarea` text NOT NULL,
  `requirement` text NOT NULL COMMENT '进入需求(格式:[{lv, Lv},...])',
  `minimapwidth` int(10) NOT NULL DEFAULT '550',
  `minimapheight` int(10) NOT NULL DEFAULT '380',
  `scene_bright` varchar(10) NOT NULL DEFAULT '0.9',
  `is_have_minimap` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '否有小地图##0:无;1:有小地图',
  `parnter_battle_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '伙伴战斗类型',
  `fuhuoscene` int(11) NOT NULL DEFAULT '0' COMMENT '复活场景',
  `reborn_xys` text NOT NULL COMMENT '复活坐标列表',
  `is_stay_pk_status` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否保留pk状态##(0没有, 1有)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='场景';
/*!40101 SET character_set_client = @saved_cs_client */;
