CREATE TABLE `base_scene_other` (
  `id` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '场景ID',
  `room_max_people` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '房间最大人数（程序容错最小50人，仅野外和主城有效）',
  `is_pvp_sputter` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '是否有pvp溅射##默认是1,没有配置默认是溅射.首个玩家100%的伤害,其他玩家25%伤害',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='场景其他配置';
