DROP TABLE IF EXISTS `base_skill`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_skill` (
  `id` int(10) unsigned NOT NULL,
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '技能名称@lang@',
  `career` int(11) NOT NULL COMMENT '所属职业:1-剑客，10-通用被动，11-怪物，12-宠物，14-坐骑，15-翅膀，16-法宝，17-神兵，18-披风，19-神兽，20-公会，21-副本。这里的职业指基础职业，同一个职业多次转生，但都属于同一基础职业。',
  `type` int(11) NOT NULL COMMENT '1主动, 2被动, 3辅助, 4.永久增益 5.天赋攻击 6.天赋防守 7.天赋通用',
  `is_passive` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '被动触发##1:触发,0:不触发',
  `share_type` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '共享类型##0:无; 1:队伍共享',
  `is_normal` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '是否普攻(0|1)',
  `is_combo` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '是否副技能(0|1)',
  `is_anger` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '是否怒气技能(0|1)',
  `refind_target` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '是否重新选取目标(0|1)',
  `mod` tinyint(2) DEFAULT '1' COMMENT '攻击模式：1单体，2群体',
  `obj` tinyint(2) NOT NULL COMMENT '1自己,2攻击目标,3选择单体目标,4朝向,5血量最少队友,6指定怪物,7主人,8.只对队友',
  `is_att` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '是否攻击##不攻击不会选择目标施放技能',
  `calc` int(11) NOT NULL COMMENT '是否计算伤害：0否，1是',
  `release` int(11) DEFAULT '1' COMMENT '技能释放模式：1普通，2蓄能，3移动施法',
  `around_hurt` int(11) NOT NULL COMMENT '群攻周围伤害比：1-1000',
  `range` int(11) NOT NULL COMMENT '群攻范围模式：1圆形，2直线，3扇形',
  `talent` int(11) NOT NULL COMMENT '天赋技能id列表[技能id,...]',
  `combo` text NOT NULL COMMENT '连技[{技能id,ms},...]',
  `bullet_type` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '子弹类型##0:普通;1:根据攻击数量(不可重复)',
  `bullet_spd` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '子弹速度（填写在主技能）',
  `bullet_att_time` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '子弹检测时间',
  `count` tinyint(2) unsigned NOT NULL DEFAULT '0' COMMENT '子弹判定次数',
  `time` int(11) NOT NULL COMMENT '技能施放时间,ms',
  `time_no` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '施放时间编号##同一个编号,只有等待技能释放时间结束才可能释放,目前1是主角的技能,0不处理',
  `skill_link` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '关联技能##[技能id,技能id...]',
  `sex` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '性别',
