DROP TABLE IF EXISTS `base_skill_buff_ui`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_skill_buff_ui` (
  `skill_id` int(10) unsigned NOT NULL COMMENT '技能id',
  `icon_id` int(10) unsigned NOT NULL COMMENT '图标id',
  `name` varchar(255) NOT NULL COMMENT '名字@lang@',
  `desc` varchar(1000) NOT NULL COMMENT '描述@lang@',
  PRIMARY KEY (`skill_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='技能buff图标配置';
/*!40101 SET character_set_client = @saved_cs_client */;
INSERT INTO `base_skill_buff_ui` VALUES (420100401,420100401,'经验加成','经验+30%'),(420100501,420100501,'经验加成','经验+30%');
DROP TABLE IF EXISTS `base_skill_lv_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_skill_lv_data` (
  `id` int(11) NOT NULL COMMENT '技能id',
  `lv` int(11) NOT NULL COMMENT '等级',
  `lv_name` varchar(500) NOT NULL COMMENT '技能名字@lang@',
  `desc` varchar(500) DEFAULT NULL COMMENT '描述@lang@',
  `condition` varchar(500) DEFAULT NULL COMMENT '学习条件',
  `power` varchar(500) DEFAULT NULL COMMENT '基础战力',
  `base_attr` varchar(500) DEFAULT NULL COMMENT '技能基础属性',
  `sec_attr` varchar(5000) NOT NULL DEFAULT '[]' COMMENT '第二属性##[{Type, Args, Value}]',
  `cd` varchar(500) DEFAULT NULL COMMENT 'cd',
  `trigger_cond` varchar(500) DEFAULT '' COMMENT '基础触发条件##[{prob, 概率}]',
  `trigger` varchar(500) DEFAULT NULL COMMENT '触发条件',
  `relate_skill_list` varchar(500) DEFAULT '[]' COMMENT '关联技能##(目前只有被动有效)成功触发时,再触发对应的关联技能[{SkillId,Lv}]',
  `assist_skill_list` varchar(500) DEFAULT '[]' COMMENT '释放辅助技能##(目前只有被动有效)成功触发时,释放对应的辅助技能[{SkillId,Lv}]',
  `must_skill_list` varchar(500) NOT NULL DEFAULT '[]' COMMENT '必然触发被动技能##(目前只有被动有效)本技能触发了,必然触发该被动, [{SkillId,Lv},...]',
  `distance` varchar(500) DEFAULT NULL COMMENT '攻击距离',
  `area` varchar(500) DEFAULT NULL COMMENT '攻击范围',
  `num` varchar(500) DEFAULT NULL COMMENT '攻击人数',
  `attr` varchar(500) DEFAULT NULL COMMENT '基础属性',
  `hurt` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '固定伤害',
  `hurt_ratio` int(11) unsigned NOT NULL DEFAULT '0' COMMENT '伤害倍率##整数,万分比',
  `effect` varchar(5000) DEFAULT NULL COMMENT '特殊效果',
  `icon` varchar(500) NOT NULL DEFAULT '' COMMENT '技能图标',
  `assist_mon_list` varchar(500) NOT NULL DEFAULT '[]' COMMENT '辅助技能的怪物列表##[{MonId, Num},...]',
  `recalc_effect` varchar(1000) NOT NULL DEFAULT '[]' COMMENT '重算效果列表##[{buffid,效果类型,替换效果列表}],效果类型0是基础属性效果,1是特殊效果类型',
  PRIMARY KEY (`id`,`lv`)
