DROP TABLE IF EXISTS `base_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_task` (
  `id` int(11) NOT NULL COMMENT '任务id',
  `name` varchar(30) NOT NULL COMMENT '任务名@lang@',
  `desc` text NOT NULL COMMENT '描述@lang@',
  `tips` text NOT NULL COMMENT '任务提示@lang@',
  `type` int(2) unsigned NOT NULL DEFAULT '0' COMMENT '任务类型',
  `chapter` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '主线章节',
  `kind` int(2) unsigned NOT NULL DEFAULT '0' COMMENT '任务种类',
  `level` int(10) unsigned NOT NULL DEFAULT '1' COMMENT '等级限制',
  `level_max` int(11) NOT NULL COMMENT '最大等级',
  `repeat` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否允许重复做',
  `realm` int(1) NOT NULL DEFAULT '0' COMMENT '阵营',
  `career` tinyint(1) NOT NULL DEFAULT '0' COMMENT '职业限制',
  `turn` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '转生次数',
  `prev` int(11) NOT NULL DEFAULT '0' COMMENT '上一个必须完成的任务id',
  `next` int(11) NOT NULL DEFAULT '0' COMMENT '下个关联任务id，即这个任务完成后触发任务',
  `start_item` text NOT NULL COMMENT '触发是获得物品',
  `end_item` text NOT NULL COMMENT '完成回收物品',
  `start_npc` text NOT NULL COMMENT '开始npc',
  `end_npc` int(11) NOT NULL DEFAULT '0' COMMENT '结束npc',
  `start_talk` int(11) NOT NULL DEFAULT '0' COMMENT '开始npc对话',
  `end_talk` int(11) NOT NULL DEFAULT '0' COMMENT '结束npc对话',
  `unfinished_talk` int(11) NOT NULL DEFAULT '0' COMMENT '未完成对话',
  `state` int(1) unsigned NOT NULL DEFAULT '0' COMMENT '任务的终结状态',
  `award_list` text NOT NULL,
  `special_goods_list` text NOT NULL COMMENT '固定物品',
  `npc_show` text NOT NULL COMMENT '默认：[] 提示：[{npcId,是否显示(0,1),场景id,x,y},...]',
  `follow_list` text NOT NULL COMMENT '跟随NPC',
  `sep` int(11) NOT NULL DEFAULT '0' COMMENT '同类排序',
  `attr_reward` varchar(1000) NOT NULL COMMENT '属性奖励',
  `main_line_order` int(11) NOT NULL DEFAULT '0' COMMENT '主线序号',
  `show_finish` int(11) NOT NULL DEFAULT '0' COMMENT '是否弹出完成界面',
  `start_guide` int(11) NOT NULL DEFAULT '0' COMMENT '是否有接任务引导',
  `end_guide` int(11) NOT NULL DEFAULT '0' COMMENT '是否有完成任务引导',
  PRIMARY KEY (`id`)
