DROP TABLE IF EXISTS `base_task_content`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `base_task_content` (
  `id` int(11) NOT NULL COMMENT '任务id',
  `phase_id` int(11) NOT NULL COMMENT '阶段id',
  `content_id` int(11) NOT NULL COMMENT '阶段内容id',
  `content_type` varchar(255) NOT NULL COMMENT '类型',
  `type_id` int(11) NOT NULL COMMENT '类型id',
  `config_id` int(11) NOT NULL COMMENT '配置id',
  `num` int(11) DEFAULT NULL COMMENT '所需数量',
  `scene_id` int(11) DEFAULT NULL COMMENT '场景id',
  `scene_x` int(11) DEFAULT NULL COMMENT '场景Xpx',
  `scene_y` int(11) DEFAULT NULL COMMENT '场景Ypx',
  `need_guide` tinyint(4) DEFAULT NULL COMMENT '是否需要寻路',
  `content_tips` varchar(1000) DEFAULT NULL COMMENT '任务阶段内容@lang@',
  `talk_id` int(11) DEFAULT NULL COMMENT '对话id',
  `show_num` int(11) NOT NULL COMMENT '显示数量',
  `need_lead` tinyint(2) NOT NULL DEFAULT '0' COMMENT '是否需要引导',
  PRIMARY KEY (`id`,`phase_id`,`content_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
